        self.user_supervisor = user_supervisor;
    }

    ///
    /// # Description
    ///
    /// Checks if the copy-on-write flag is set.
    ///
    /// # Returns
    ///
    /// `true` if the copy-on-write flag is set, `false` otherwise.
    ///
    #[inline(always)]
    pub fn is_cow(&self) -> bool {
        matches!(self.cow, CopyOnWriteFlag::CopyOnWrite)
    }

