    /// Sets the copy-on-write flag.
    ///
    /// # Parameters
    ///
    /// - `cow`: The copy-on-write flag.
    ///
    #[inline(always)]
    pub fn set_cow(&mut self, cow: CopyOnWriteFlag) {
        self.cow = cow;
    }
